#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=198.51.100.66/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Block bad host'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=198.51.100.66/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Block bad host'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Guests stay in'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Guests stay in'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=OT no internet'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=OT no internet'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   LAN web: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network
#   LAN DNS: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network
#   LAN DNS-2: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network
#   Inbound web: the source of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network; the destination of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network
#   Inbound mail: the source of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network; the destination of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network
#   Admins SSH: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network
#   Admins RDP: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network
#   SCADA to PLCs: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth3, and a rule of Google Cloud names no zone: give the networks behind eth3 with --zone-network
#   DMZ updates: the source of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network
#   Rate limited mail: not converted: match module 'limit'; the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-n
#   Ping the DMZ: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Google Cloud names no zone: give the networks behind eth2 with --zone-network
#   Partner tunnel: the source of the rule is in zone eth1, and a rule of Google Cloud names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth0, and a rule of Google Cloud names no zone: give the networks behind eth0 with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
